{
  "findings": [
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain does not have logging enabled, which can make it difficult to monitor and troubleshoot issues."
    },
    {
      "check_id": "CKV_AWS_317",
      "title": "Ensure Elasticsearch Domain Audit Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Audit logging is not enabled for the Elasticsearch domain, which can hinder the ability to track access and changes for compliance and security purposes."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain does not specify a TLS security policy, which may result in the use of outdated or insecure TLS versions."
    },
    {
      "check_id": "CKV_AWS_137",
      "title": "Ensure that Elasticsearch is configured inside a VPC",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain is configured inside a VPC, which is good, but the configuration does not explicitly include all required VPC options for security."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Ensure ElasticSearch/OpenSearch has dedicated master node enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain does not have dedicated master nodes enabled, which can impact cluster stability and performance."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Ensure encryption at rest is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "Encryption at rest is disabled, which can expose sensitive data stored in the Elasticsearch domain to unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_elasticsearch_domain\" \"log_search_database\" {\n  domain_name           = \"enterprise-log-analytics-es\"\n  elasticsearch_version = \"7.10\"\n  cluster_config {\n    instance_type  = var.elasticsearch_instance_type\n    instance_count = 2\n    dedicated_master_enabled = true\n    dedicated_master_type = var.elasticsearch_master_instance_type\n    dedicated_master_count = 3\n  }\n  vpc_options {\n    subnet_ids         = [aws_subnet.data_subnet_az1.id]\n    security_group_ids = [aws_security_group.elasticsearch_sg.id]\n  }\n  ebs_options {\n    ebs_enabled = true\n    volume_size = 20\n    volume_type = \"gp2\"\n  }\n  encrypt_at_rest {\n    enabled = true\n  }\n  node_to_node_encryption {\n    enabled = true\n  }\n  log_publishing_options {\n    log_type = \"INDEX_SLOW_LOGS\"\n    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_index_slow_logs.arn\n  }\n  log_publishing_options {\n    log_type = \"SEARCH_SLOW_LOGS\"\n    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_search_slow_logs.arn\n  }\n  log_publishing_options {\n    log_type = \"ES_APPLICATION_LOGS\"\n    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_application_logs.arn\n  }\n  log_publishing_options {\n    log_type = \"AUDIT_LOGS\"\n    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_audit_logs.arn\n  }\n  domain_endpoint_options {\n    enforce_https = true\n    tls_security_policy = \"Policy-Min-TLS-1-2-2019-07\"\n  }\n}",
  "fix_summary": "Enabled encryption at rest and node-to-node encryption. Configured dedicated master nodes for cluster stability. Added log publishing options for various Elasticsearch logs, including audit logs. Enforced HTTPS with an up-to-date TLS policy."
}
